/**
 * Cloudflare Worker - 太吾绘卷功法图鉴
 * v4c: Add hover tooltip to recommended gongfa
 */

const HTML_BASE64 = "";

/**
 * 路由分发 + KV API + 静态HTML
 */
export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    // ============ KV API: BD方案存取 ============

    // 获取BD方案列表
    if (url.pathname === '/api/bd/list' && request.method === 'GET') {
      return handleBDList(env);
    }

    // 保存BD方案
    if (url.pathname === '/api/bd/save' && request.method === 'POST') {
      return handleBDSave(request, env);
    }

    // 删除BD方案
    if (url.pathname === '/api/bd/delete' && request.method === 'DELETE') {
      return handleBDDelete(url, env);
    }

    // ============ KV API: 推荐功法存取 ============

    // 获取推荐功法列表
    if (url.pathname === '/api/rec/list' && request.method === 'GET') {
      return handleRecList(env);
    }

    // 保存推荐功法
    if (url.pathname === '/api/rec/save' && request.method === 'POST') {
      return handleRecSave(request, env);
    }

    // 删除推荐功法
    if (url.pathname === '/api/rec/delete' && request.method === 'DELETE') {
      return handleRecDelete(url, env);
    }

    // ============ CORS 预检 ============
    if (request.method === 'OPTIONS') {
      return new Response(null, {
        headers: {
          'Access-Control-Allow-Origin': '*',
          'Access-Control-Allow-Methods': 'GET, POST, DELETE, OPTIONS',
          'Access-Control-Allow-Headers': 'Content-Type'
        }
      });
    }

    // ============ 健康检查 ============
    if (url.pathname === '/health' || url.pathname === '/ping') {
      return new Response(JSON.stringify({ status: 'ok', service: 'taiwu-game' }), {
        headers: { 'Content-Type': 'application/json' }
      });
    }

    // ============ 静态HTML ============
    const htmlBytes = atob(HTML_BASE64);
    const html = new TextDecoder('utf-8').decode(
      Uint8Array.from(htmlBytes, c => c.charCodeAt(0))
    );

    return new Response(html, {
      status: 200,
      headers: {
        'Content-Type': 'text/html; charset=UTF-8',
        'Cache-Control': 'public, max-age=86400',
        'X-Content-Type-Options': 'nosniff',
        'X-Frame-Options': 'SAMEORIGIN',
        'Referrer-Policy': 'no-referrer-when-downgrade'
      }
    });
  }
};

/**
 * 获取BD方案列表
 * KV key 格式: bd_preset:<id>
 */
async function handleBDList(env) {
  try {
    if (!env.BD_KV) {
      return jsonResponse({ error: 'KV not configured', presets: [] }, 200);
    }
    const listing = await env.BD_KV.list({ prefix: 'bd_preset:' });
    const presets = [];
    for (const key of listing.keys) {
      const value = await env.BD_KV.get(key.name);
      if (value) {
        try {
          presets.push(JSON.parse(value));
        } catch (e) {
          // skip invalid JSON
        }
      }
    }
    return jsonResponse(presets);
  } catch (e) {
    return jsonResponse({ error: e.message }, 500);
  }
}

/**
 * 保存BD方案到KV
 * Body: { id, name, brief, cuipo, desc, bd_str }
 */
async function handleBDSave(request, env) {
  try {
    if (!env.BD_KV) {
      return jsonResponse({ success: false, error: 'KV not configured' }, 500);
    }
    const body = await request.json();
    if (!body || !body.id || !body.name || !body.bd_str) {
      return jsonResponse({ success: false, error: 'Missing required fields (id, name, bd_str)' }, 400);
    }
    // 限制单个方案大小 (1MB)
    const valueStr = JSON.stringify(body);
    if (valueStr.length > 1024 * 1024) {
      return jsonResponse({ success: false, error: 'BD preset too large (max 1MB)' }, 400);
    }
    // 限制方案数量 (1000个)
    const listing = await env.BD_KV.list({ prefix: 'bd_preset:' });
    if (listing.keys.length >= 1000) {
      return jsonResponse({ success: false, error: 'Too many presets (max 1000)' }, 400);
    }
    const key = 'bd_preset:' + body.id;
    await env.BD_KV.put(key, valueStr);
    return jsonResponse({ success: true, id: body.id, count: listing.keys.length + 1 });
  } catch (e) {
    return jsonResponse({ success: false, error: e.message }, 500);
  }
}

/**
 * 删除BD方案
 * Query: ?id=<preset_id>
 */
async function handleBDDelete(url, env) {
  try {
    if (!env.BD_KV) {
      return jsonResponse({ success: false, error: 'KV not configured' }, 500);
    }
    const id = url.searchParams.get('id');
    if (!id) {
      return jsonResponse({ success: false, error: 'Missing id parameter' }, 400);
    }
    const key = 'bd_preset:' + id;
    await env.BD_KV.delete(key);
    return jsonResponse({ success: true, id: id });
  } catch (e) {
    return jsonResponse({ success: false, error: e.message }, 500);
  }
}

/**
 * 获取推荐功法列表
 * KV key 格式: rec:<id>
 * 返回按分类组织的对象: { "内功": { "通用类": [...], ... }, ... }
 */
async function handleRecList(env) {
  try {
    if (!env.BD_KV) {
      return jsonResponse({ "内功": {}, "摧破": {}, "轻灵": {}, "护体": {}, "奇窍": {} }, 200);
    }
    const listing = await env.BD_KV.list({ prefix: 'rec:' });
    const result = {};
    const categories = ['内功', '摧破', '轻灵', '护体', '奇窍'];
    categories.forEach(c => { result[c] = {}; });

    for (const key of listing.keys) {
      const value = await env.BD_KV.get(key.name);
      if (value) {
        try {
          const item = JSON.parse(value);
          // 从 key 提取 id: rec:<id>
          item._id = key.name.substring(4); // remove "rec:" prefix
          const cat = item.category || '摧破';
          const subcat = item.subcategory || '通用类';
          if (!result[cat]) result[cat] = {};
          if (!result[cat][subcat]) result[cat][subcat] = [];
          result[cat][subcat].push({
            n: item.n,
            d: item.d || '',
            note: item.note || '',
            sect: item.sect || '',
            grade: item.grade || 9,
            _id: item._id
          });
        } catch (e) {
          // skip invalid JSON
        }
      }
    }
    return jsonResponse(result);
  } catch (e) {
    return jsonResponse({ error: e.message }, 500);
  }
}

/**
 * 保存推荐功法到KV
 * Body: { id, category, subcategory, n, sect, grade, d, note }
 */
async function handleRecSave(request, env) {
  try {
    if (!env.BD_KV) {
      return jsonResponse({ success: false, error: 'KV not configured' }, 500);
    }
    const body = await request.json();
    if (!body || !body.id || !body.n) {
      return jsonResponse({ success: false, error: 'Missing required fields (id, n)' }, 400);
    }
    // 限制大小
    const valueStr = JSON.stringify(body);
    if (valueStr.length > 100 * 1024) {
      return jsonResponse({ success: false, error: 'Record too large (max 100KB)' }, 400);
    }
    // 限制数量 (2000条)
    const listing = await env.BD_KV.list({ prefix: 'rec:' });
    if (listing.keys.length >= 2000) {
      return jsonResponse({ success: false, error: 'Too many records (max 2000)' }, 400);
    }
    const key = 'rec:' + body.id;
    await env.BD_KV.put(key, valueStr);
    return jsonResponse({ success: true, id: body.id, count: listing.keys.length + 1 });
  } catch (e) {
    return jsonResponse({ success: false, error: e.message }, 500);
  }
}

/**
 * 删除推荐功法
 * Query: ?id=<rec_id>
 */
async function handleRecDelete(url, env) {
  try {
    if (!env.BD_KV) {
      return jsonResponse({ success: false, error: 'KV not configured' }, 500);
    }
    const id = url.searchParams.get('id');
    if (!id) {
      return jsonResponse({ success: false, error: 'Missing id parameter' }, 400);
    }
    const key = 'rec:' + id;
    await env.BD_KV.delete(key);
    return jsonResponse({ success: true, id: id });
  } catch (e) {
    return jsonResponse({ success: false, error: e.message }, 500);
  }
}

/**
 * JSON Response helper
 */
function jsonResponse(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: {
      'Content-Type': 'application/json; charset=UTF-8',
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'GET, POST, DELETE, OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type'
    }
  });
}
